510			throw new TypeError(`${name} must be an ordinary detached Uint8Array`);
511		}
512		if (
513			INTRINSIC_GET_PROTOTYPE_OF(value) !== INTRINSIC_UINT8_ARRAY_PROTOTYPE ||
514			!(backing instanceof INTRINSIC_ARRAY_BUFFER) ||
515			INTRINSIC_GET_PROTOTYPE_OF(backing) !== INTRINSIC_ARRAY_BUFFER_PROTOTYPE ||
516			resizable ||
517			byteOffset !== 0 ||
518			typeof byteLength !== "number" ||
519			byteLength !== backingByteLength ||
520			(expectedLength !== undefined && byteLength !== expectedLength)
521		) {
522			throw new TypeError(`${name} must be an ordinary detached Uint8Array`);
523		}
524		const output = new INTRINSIC_UINT8_ARRAY(byteLength);
525		Reflect.apply(INTRINSIC_UINT8_ARRAY_SET, output, [new INTRINSIC_UINT8_ARRAY(backing, 0, byteLength)]);
526		return output;
527	}
