544		let backingByteLength: unknown;
545		let byteLength: unknown;
546		let byteOffset: unknown;
547		let resizable = false;
548		try {
549			backing = Reflect.apply(INTRINSIC_TYPED_ARRAY_BUFFER_GETTER, value, []);
550			backingByteLength = Reflect.apply(INTRINSIC_ARRAY_BUFFER_BYTE_LENGTH_GETTER, backing, []);
551			byteLength = Reflect.apply(INTRINSIC_TYPED_ARRAY_BYTE_LENGTH_GETTER, value, []);
552			byteOffset = Reflect.apply(INTRINSIC_TYPED_ARRAY_BYTE_OFFSET_GETTER, value, []);
553			if (INTRINSIC_ARRAY_BUFFER_RESIZABLE_GETTER !== undefined) {
554				resizable = Reflect.apply(INTRINSIC_ARRAY_BUFFER_RESIZABLE_GETTER, backing, []) === true;
555			}
556		} catch {
557			throw new TypeError(`v3 room ${purpose} state is invalid`);
558		}
559		if (
560			INTRINSIC_GET_PROTOTYPE_OF(value) !== INTRINSIC_UINT8_ARRAY_PROTOTYPE ||
561			!(backing instanceof INTRINSIC_ARRAY_BUFFER) ||
562			INTRINSIC_GET_PROTOTYPE_OF(backing) !== INTRINSIC_ARRAY_BUFFER_PROTOTYPE ||
563			resizable ||
564			byteOffset !== 0 ||
565			typeof byteLength !== "number" ||
566			byteLength !== backingByteLength
