568			throw new TypeError(`v3 room ${purpose} state is invalid`);
569		}
570		const exactState = new INTRINSIC_UINT8_ARRAY(byteLength);
571		Reflect.apply(INTRINSIC_UINT8_ARRAY_SET, exactState, [new INTRINSIC_UINT8_ARRAY(backing, byteOffset, byteLength)]);
