573		let decodedState: unknown;
574		try {
575			decodedState = decodeCanonical(exactState, { maxBytes: 32_768, maxDepth: 16, maxItems: 16_384 });
576		} catch {
577			throw new TypeError(`v3 room ${purpose} state is invalid`);
578		}
579		if (!sameBytes(encodeCanonical(decodedState), exactState)) {
580			throw new TypeError(`v3 room ${purpose} state is not canonical`);
581		}
582		if (
583			purpose === "genesis" &&
584			decodedState !== null &&
585			typeof decodedState === "object" &&
586			!Array.isArray(decodedState) &&
