672	 * @param input - Closed product-owned blueprint, authority and signer evidence.
673	 * @returns Detached exact genesis material for the room session.
674	 */
675	export async function createV3RoomCreatorInviteMaterial(
676		input: V3RoomCreatorInviteMaterialInput
677	): Promise<V3RoomCreatorInviteMaterial> {
678		const record = exactRecord(input, [
679			"blueprintDigest",
680			"exactCanonicalApplicationStateBytes",
681			"exactCanonicalLatchedAclBytes",
682			"exactCanonicalParametersCarrierBytes",
683			"exactCanonicalProfileBytes",
684			"exactCanonicalSignerSetBytes",
685			"objectId",
686			"signGenesisAnchorDigest",
687		]);
688		if (
689			record === undefined ||
690			typeof record.blueprintDigest !== "string" ||
691			!/^[0-9a-f]{64}$/u.test(record.blueprintDigest) ||
692			typeof record.objectId !== "string" ||
693			!parseStorageObjectId(record.objectId).ok ||
694			typeof record.signGenesisAnchorDigest !== "function"
695		) {
696			throw new TypeError("v3 room creator invite input is invalid");
697		}
698		const blueprintDigest = record.blueprintDigest;
699		const objectId = record.objectId;
700		const signGenesisAnchorDigest = record.signGenesisAnchorDigest as (digest: Uint8Array) => Promise<Uint8Array>;
701		const exactCanonicalApplicationStateBytes = normalizeApplicationStateBytes(
702			record.exactCanonicalApplicationStateBytes,
703			"genesis"
704		);
705		const stateDigest = digest("ts-drp/state/v3", exactCanonicalApplicationStateBytes);
706		const exactCanonicalLatchedAclBytes = strictCanonicalBytes(
707			record.exactCanonicalLatchedAclBytes,
708			"exactCanonicalLatchedAclBytes"
709		);
710		const exactCanonicalParametersCarrierBytes = strictCanonicalBytes(
711			record.exactCanonicalParametersCarrierBytes,
712			"exactCanonicalParametersCarrierBytes"
713		);
714		const exactCanonicalProfileBytes = strictCanonicalBytes(
715			record.exactCanonicalProfileBytes,
716			"exactCanonicalProfileBytes"
717		);
718		const exactCanonicalSignerSetBytes = strictCanonicalBytes(
719			record.exactCanonicalSignerSetBytes,
720			"exactCanonicalSignerSetBytes"
721		);
722		const emptyRoot = hex(new CompactMerkleAccumulator().root());
