724			aclDigest: digest("ts-drp/latched-acl/v3", exactCanonicalLatchedAclBytes),
725			archiveIndexRoot: emptyRoot,
726			blueprintDigest,
727			cryptoSuiteId: "ed25519-sha256-v3",
728			cutDigest: "0".repeat(64),
729			epoch: 0,
730			historyRoot: emptyRoot,
731			historySize: 0,
732			kind: "drp-epoch-anchor",
733			objectId,
734			parametersDigest: digest("ts-drp/parameters/v3", exactCanonicalParametersCarrierBytes),
735			previousAnchor: "0".repeat(64),
736			profileDigest: digest("ts-drp/profile/v3", exactCanonicalProfileBytes),
737			protocolMajor: 3,
738			signerSetDigest: digest("ts-drp/signer-set/v3", exactCanonicalSignerSetBytes),
